def defs(c1,c2,c3):
    return f'''<defs>
<linearGradient id="bg" x1="0" y1="0" x2="0" y2="1"><stop stop-color="{c1}"/><stop offset="1" stop-color="{c2}"/></linearGradient>
<radialGradient id="glow"><stop stop-color="{c3}" stop-opacity=".5"/><stop offset="1" stop-color="{c3}" stop-opacity="0"/></radialGradient>
<filter id="soft"><feGaussianBlur stdDeviation="8"/></filter>
</defs>'''

def base(c1,c2,c3,art):
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="690" height="1000" viewBox="0 0 690 1000">
{defs(c1,c2,c3)}
<rect width="690" height="1000" fill="url(#bg)"/>
<circle cx="545" cy="155" r="180" fill="url(#glow)"/>
<g opacity=".16" fill="#fff"><circle cx="84" cy="110" r="6"/><circle cx="145" cy="70" r="3"/><circle cx="605" cy="260" r="5"/><circle cx="72" cy="420" r="4"/><circle cx="620" cy="520" r="3"/></g>
{art}
</svg>'''

